def parse_percent(text: str) -> tuple[str, int]:
    """Turn user input such as "alice=50" into ("alice", 50)."""
    name, separator, number = text.partition("=")
    if not separator or not name:
        raise MoneyError(f"expected NAME=PERCENT, for example alice=50: {text!r}")
    if not (number.isascii() and number.isdigit()) or int(number) == 0:
        raise MoneyError(f"percent must be a whole number above zero: {text!r}")
    return name, int(number)


